      {filtered.length ? <><div className="purchase-table-wrap"><table className="purchase-table"><thead><tr><th>{T.receipt}</th><th>{T.supplier}</th><th>{T.date}</th><th>{T.items}</th><th>{T.total}</th><th>{T.paid}</th><th>{T.due}</th><th>{T.status}</th><th>{T.actions}</th></tr></thead><tbody>{filtered.map(r=><tr key={r.id} className={selected?.id===r.id?'is-selected':''} onClick={()=>setSelectedId(r.id)}><td><b className="purchase-number">{r.number}</b><small>{r.openedBy||actor}</small></td><td><b>{r.supplierName}</b></td><td>{r.date}</td><td>{(r.items||[]).length} <small>· {totalQty(r)}</small></td><td><b>{fmt(receiptTotal(r))}</b></td><td>{fmt(r.paid)}</td><td><b className={remaining(r)>0?'purchase-debt':''}>{fmt(remaining(r))}</b></td><td><span className={'purchase-status '+(r.status==='closed'?'closed':'open')}><i/>{r.status==='closed'?T.closed:T.open}</span></td><td><div className="purchase-row-actions"><button type="button" title={T.preview} onClick={e=>{e.stopPropagation();setPreview(r)}}><Eye size={15}/></button><button type="button" title={T.edit} onClick={e=>{e.stopPropagation();startEdit(r)}}><Pencil size={15}/></button><button type="button" title={T.print} onClick={e=>{e.stopPropagation();print(r)}}><Printer size={15}/></button><button type="button" className="danger" title={T.delete} onClick={e=>{e.stopPropagation();remove(r)}}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>
      <div className="purchase-register-foot"><span>{filtered.length} / {rows.length}</span><div><button type="button" onClick={()=>move(-1)} disabled={filtered.findIndex(r=>r.id===selected?.id)<=0}><ChevronLeft size={15}/></button><button type="button" onClick={()=>move(1)} disabled={filtered.findIndex(r=>r.id===selected?.id)>=filtered.length-1}><ChevronRight size={15}/></button></div></div></> : <div className="purchase-empty"><span><SearchX size={28}/></span><h3>{T.empty}</h3><p>{T.emptyHint}</p><button type="button" className="purchase-primary" onClick={startNew}><Plus size={15}/>{T.create}</button></div>}
